    """Yield tuples of *size* items, with a shorter final tuple if needed."""
    while True:
        chunk = tuple(islice(flat, size))
        if not chunk:
            return
        yield chunk


def _build(flat, dims):
    """Build one nested block with shape *dims* from *flat*.

    Returns an empty tuple only when the input is exhausted.
    """
    if len(dims) == 1:
        return tuple(islice(flat, dims[0]))
    children = []
    for _ in range(dims[0]):
        child = _build(flat, dims[1:])
        if not child:
            break
        children.append(child)
    return tuple(children)


def _reshape_dims(matrix, dims):
    """Yield the blocks of a reshape to the nested shape *dims*."""
    flat = _flatten(matrix)
    if len(dims) == 1:
        yield from islice(flat, dims[0])
        return
    for _ in range(dims[0]):
        block = _build(flat, dims[1:])
        if not block:
            return
        yield block


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int):
        if shape < 1:
            raise ValueError("number of columns must be a positive integer")
        return _chunks(_flatten(matrix), shape)

    try:
        dims = tuple(shape)
    except TypeError:
        raise TypeError("shape must be an integer or an iterable of integers")
    if not dims:
        raise ValueError("shape must contain at least one dimension")
    for dim in dims:
        if not isinstance(dim, int) or dim < 1:
            raise ValueError("every dimension must be a positive integer")

    return _reshape_dims(matrix, dims)

from itertools import chain, repeat


def ncycles(iterable, n):
    """Returns the sequence elements *n* times

    >>> list(ncycles(["a", "b"], 3))
    ['a', 'b', 'a', 'b', 'a', 'b']

    """
    if n < 0:
        raise ValueError("n must not be negative")
    items = tuple(iterable)
    return chain.from_iterable(repeat(items, n))

from itertools import islice


def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    if n < 1:
        raise ValueError("n must be at least 1")

    iterator = iter(iterable)

    def generate():
        while True:
            chunk = list(islice(iterator, n))
            if not chunk:
                return
            if strict and len(chunk) < n:
                raise ValueError("iterable is not divisible by n")
            yield chunk

    return generate()

from itertools import islice, zip_longest


def zip_offset(*iterables, offsets, longest=False, fillvalue=None):
    """``zip`` the input *iterables* together, but offset the `i`-th iterable
    by the `i`-th item in *offsets*.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1)))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e')]

    This can be used as a lightweight alternative to SciPy or pandas to analyze
    data sets in which some series have a lead or lag relationship.

    By default, the sequence will end when the shortest iterable is exhausted.
    To continue until the longest iterable is exhausted, set *longest* to
    ``True``.

        >>> list(zip_offset('0123', 'abcdef', offsets=(0, 1), longest=True))
        [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e'), (None, 'f')]

    By default, ``None`` will be used to replace offsets beyond the end of the
    sequence. Specify *fillvalue* to use some other value.

    """
    if len(offsets) != len(iterables):
        raise ValueError('offsets must have one entry per iterable')
    for offset in offsets:
        if offset < 0:
            raise ValueError('offsets must be non-negative')

    # Validate and create iterators now, so errors surface at call time.
    shifted = [
        islice(iter(iterable), offset, None)
        for iterable, offset in zip(iterables, offsets)
    ]

    if longest:
        return zip_longest(*shifted, fillvalue=fillvalue)
    return zip(*shifted)

from itertools import islice
from math import prod


def _is_scalar(value):
    """Return True for bytes, strings and non-iterables."""
    if isinstance(value, (bytes, str)):
        return True
    try:
        iter(value)
    except TypeError:
        return True
    return False


def _flatten(items):
    """Yield every scalar found in *items*, depth first."""
    for item in items:
        if _is_scalar(item):
            yield item
        else:
            yield from _flatten(item)


def _chunks(items, size):
    """Yield tuples of *size* items; an incomplete final group is dropped."""
    items = iter(items)
    while True:
        group = tuple(islice(items, size))
        if len(group) < size:
            return
        yield group


def _build(items, dims):
    """Build a nested tuple with shape *dims* from the iterator *items*."""
    if not dims:
        return next(items)
    return tuple(_build(items, dims[1:]) for _ in range(dims[0]))


def _reshape_flat(flat, dims):
    """Yield items shaped as *dims* from the flat scalar iterable *flat*."""
    inner = dims[1:]
    step = prod(inner)
    for chunk in islice(_chunks(flat, step), dims[0]):
        yield _build(iter(chunk), inner)


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int):
        if shape < 1:
            raise ValueError("number of columns must be at least 1")
        return _chunks(_flatten(matrix), shape)

    dims = tuple(shape)
    if not dims:
        raise ValueError("shape must not be empty")
    for dim in dims:
        if not isinstance(dim, int):
            raise TypeError("shape dimensions must be integers")
        if dim < 1:
            raise ValueError("shape dimensions must be at least 1")

    return _reshape_flat(_flatten(matrix), dims)

from itertools import chain, repeat


def ncycles(iterable, n):
    """Returns the sequence elements *n* times

    >>> list(ncycles(["a", "b"], 3))
    ['a', 'b', 'a', 'b', 'a', 'b']

    """
    if n < 0:
        raise ValueError("n must be non-negative")
    items = tuple(iterable)
    return chain.from_iterable(repeat(items, n))
